--作为房主进入房间的入口
function RegionQuestMgr:OverseaRegionalBossCreateRoomReq(activityType, activityContentId, activityUuid, activityPrefabId, bossTypeId, questId, cb)
    local parameters = {
        questId = questId,
        bossTypeId = bossTypeId
    }
    
    GameUtils.Request(Interfaces.OverseaRegionalBossCreateRoom, {bossTypeId = bossTypeId, questId = questId, activityUuid = activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self:__init()     --初始化

        if activityPrefabId > 0 then
            self.useHP = 1
        else
            self.consumeTimes = 1
        end

        self._isHouseOwn = true
        self:InitHouseInfo(activityType, activityContentId, activityUuid, activityPrefabId, questId, bossTypeId, jsonData.roomId)

        -- 添加事件
        -- self.eventOnTcpDisconnect = Events.AddListener(Constants.EventNames.GAME_TCP_DISCONNECT, Bind(self, self.OnTcpDisconnect))
        self.eventOnTcpConnect = Events.AddListener(Constants.EventNames.GAME_TCP_CONNECT, Bind(self, self.OnTcpConnect))
        self.eventOnTeamRoomReconnect = Events.AddListener(Constants.EventNames.TeamRoomReconnectResponse, Bind(self, self.OnTeamRoomReconnect))
        self.eventOnBackToHome = Events.AddListener(Constants.EventNames.ExecuteBackHome, Bind(self, self.OnBackToHome))

        self._ownInfo.mainTeamSet = {}
        local str = checkString(jsonData.mainTeamSet)
        local t = checkTable(table.deserialize(str))

        if t[1] then
            for k, v in pairs(t[1].cardsInfo) do
                if checkNumber(v.refId) > 0 then
                    v.cardInfo = cardComponent:GetCardById(v.refId)
                end
            end
        end
        if t[1] then
            self._ownInfo.mainTeamSet = t[1]
        end
        self._ownInfo.readyState = 0

        local playerComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local dojo = playerComp.playerDojo
        self._ownInfo.playerInfo = {
            playerId = dojo.playerId,
            name = dojo.playerName,
            level = dojo.level,
            avatar = dojo.playerAvatar,
            avatarFrame = dojo.playerAvatarFrame,
        }

        if cb then
            cb()
        end
    end)
end

--被邀请进入房间的入口
function RegionQuestMgr:MatchCreateRoomEntry(data, questId)
    local activityInfo = checkTable(data.mainData.activity)
    local activityType = checkNumber(activityInfo.type)
    local activityContentId = checkNumber(activityInfo.contentId)
    local activityUuid = checkNumber(activityInfo.id)
    local activityPrefabId = checkNumber(activityInfo.prefab)
    local bossTypeId = data.mainData.regionalBossData.bossTypeId
    
    local comp = AnnihilationUtils.GetComponent(activityPrefabId)
    if isNotNull(comp.SetActivityData) then
        comp:SetActivityData(activityType, activityContentId, activityUuid, activityPrefabId)
    end
    if isNotNull(comp.RequestActivityHome) then
        comp:RequestActivityHome()   -- 这里请求一下活动的home页数据，不然没有活动体力的数据
    end

    self:__init()     --初始化
    self._isHouseOwn = false

    if activityType > 0 then
        self.useHP = 1
    else
        self.consumeTimes = 1
    end

    self:InitHouseInfo(activityType, activityContentId, activityUuid, activityPrefabId, questId, bossTypeId, data.roomId)
    self._ownInfo = {}
    self._otherInfo = {}

    -- 添加事件
    -- self.eventOnTcpDisconnect = Events.AddListener(Constants.EventNames.GAME_TCP_DISCONNECT, Bind(self, self.OnTcpDisconnect))
    self.eventOnTcpConnect = Events.AddListener(Constants.EventNames.GAME_TCP_CONNECT, Bind(self, self.OnTcpConnect))
    self.eventOnTeamRoomReconnect = Events.AddListener(Constants.EventNames.TeamRoomReconnectResponse, Bind(self, self.OnTeamRoomReconnect))
    self.eventOnBackToHome = Events.AddListener(Constants.EventNames.ExecuteBackHome, Bind(self, self.OnBackToHome))

    local t = checkTable(table.deserialize(data.mainData.mainTeamSet))
    self._otherInfo.mainTeamSet = {}
    if t[1] then
        self._otherInfo.mainTeamSet = t[1]
    end
    self._otherInfo.playerInfo = checkTable(data.mainData.playerInfo)
    self._otherInfo.readyState = 0
    self._otherInfo.isRobot = 0


    self._ownInfo.playerInfo = checkTable(data.inviteData.playerInfo)
    self._ownInfo.mainTeamSet = {}
    local t = checkTable(table.deserialize(data.inviteData.subTeamSet))
    if t[1] then
        self._ownInfo.mainTeamSet = t[1]
    end
    self._ownInfo.readyState = 0

    self._houseState = HouseState.InviteSuc

    local needLoadScene = self:IsNeedLoadScene()

    CS.UINavigationBarRoot.Instance:SetActive(false)
    GameUtils.ShowBlackOverlay(nil, function()
        if needLoadScene then
            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
        end
        ---关闭所有的窗口
        local needWaitDialogClose = false
        local coWait = CS.Engine.Lib.CoWait.Start()
        local support = require('Frame.support')
        for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
            local isRemove = string.isEmpty(v.Argument.extra)
            local coClose = UIModule.CloseDialog(v, isRemove)
            if not isNull(coClose) then
                needWaitDialogClose = true
                coWait:Coroutine(coClose)
            end
        end
        UIModule.CurrentScreen.dialogs:Clear()
        while needWaitDialogClose and not coWait.IsFinish do
            coroutine.yield()
        end
        CS.Engine.UI.UIModule.ResetStack()
        if needLoadScene then
            KCookie.Set(Constants.UICacheDataKeys.OVERSEA_MANAGER_SCENE_STATE, 1)
            cs_coroutine.yield_return(UIModule.OpenScreen(UIArgs(Constants.UITypeIds.UISceneHome), true, nil))
            ---@type XMainHome
            local env = UIModule.CurrentScreen.Env
            cs_coroutine.yield_return(env:AsyncLoadingResources())
            UIModule.CurrentScreen.isLoadingFinished = true
            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.Normal
        end
        
        --主界面关掉
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)

        cs_coroutine.yield_return(UIModule.OpenDialog({ id = comp:GetTeamUITypeId() }))
    end)
end

