--玩家准备/取消准备
function RegionQuestMgr:ReadyReq(data)
    data.activityUuid = self._houseData.activityUuid
    data.isConsume = self.useHP
    data.times = self.consumeTimes
    AppService:GetInstance():SendTcpData(Constants.Packets.ReadyReq, data)
end

--玩家准备结果 
function RegionQuestMgr:HandleReadyResponse(data)
    if BattleViewMgr then return end    -- 如果进入战斗了，就不再响应房间的消息了
    if checkNumber(data.result) ~= 0 then
        local msg = AnnihilationUtils.GetServerErrorMgr(checkNumber(data.result))
        GameUtils.Toast(msg)
        if checkNumber(data.result) == 201 then
            local activityPrefabId = self._houseData.activityPrefabId
            local comp = AnnihilationUtils.GetComponent(activityPrefabId)
            comp:BuyHP()
        end
        return
    end

    self._ownInfo.readyState = 0
    self._otherInfo.readyState = 0

    local t = checkTable(data.readyPlayerIds)
    for k, v in pairs(t) do
        if checkNumber(self._ownInfo.playerInfo.playerId) == checkNumber(v) then
            self._ownInfo.readyState = 1
        elseif checkNumber(self._otherInfo.playerInfo.playerId) == checkNumber(v) then
            self._otherInfo.readyState = 1
        end
    end
    
    -- 房主不用准备，房客准备了就算准备好可以开始了
    local info = self:GetHouseMemberInfo()
    if checkNumber(info.readyState) == 1 then
        self._houseState = HouseState.ReadySuc
    end

    Events.Broadcast(Constants.EventNames.RegionTeamReadey)
end

