--回复应答给房主
function RegionQuestMgr:HandleFriendRelpyInitiativeResPonse(data)
    if BattleViewMgr then return end    -- 如果进入战斗了，就不再响应房间的消息了
    if checkNumber(data.result) ~= 0 then
        return
    end
    if checkNumber(data.reply) == 0 then
        GameUtils.Toast(localize("拒绝"))
        return
    end

    self._otherInfo = {}
    self._otherInfo.playerInfo = checkTable(data.inviteData.playerInfo)
    self._otherInfo.mainTeamSet = {}
    local t = checkTable(table.deserialize(data.inviteData.subTeamSet))
    if t[1] then
        self._otherInfo.mainTeamSet = t[1]
    end

    self._otherInfo.isRobot = checkNumber(data.inviteData.isRobot)
    if self._otherInfo.isRobot == 1 then
        self._otherInfo.readyState = 1
    end

    self:RefreshRoleModel()
    self._houseState = HouseState.InviteSuc     
    Events.Broadcast(Constants.EventNames.RegionTeamInviteResult, data)

    if self:GetRecruitState() == 1 then
        self:RecruitReq()   -- 进来人以后关闭招募状态
        self.autoRecruit = true
    end
end

--一方主动退出房间
function RegionQuestMgr:QuitReq()
