end

--有人退出房间
function RegionQuestMgr:HandleQuitTeamRoomResponse(data)
    if BattleViewMgr then return end    -- 如果进入战斗了，就不再响应房间的消息了
    if isNull(data) then return end

    local otherPlayerInfo = self._otherInfo.playerInfo
    if isNull(otherPlayerInfo) then
        return
    end
    local otherPlayerId = otherPlayerInfo.playerId
    if checkNumber(data.quitPlayerId) == checkNumber(otherPlayerId) then
        -- 对方退出房间
        if self._isHouseOwn then
            -- 房客退出
            self._ownInfo.readyState = 0
            self._otherInfo = {}
            self._houseState = HouseState.None
        
            Events.Broadcast(Constants.EventNames.RegionTeamInviteResult, nil)
            Events.Broadcast(Constants.EventNames.RegionTeamReadey)
        
            self:RefreshRoleModel()
        
            if self.autoRecruit then
                self.autoRecruit = false
                self:RecruitReq()
            end
        else
            -- 房主退出
            local social = AppService:GetInstance():GetSocialLine()
            social:ExitTeamRoom()
            social:ExitVoiceRoom()
        
            self._kickOutState = 2
            Events.Broadcast(Constants.EventNames.RegionTeamQuite, data)
        end
        
    end    
end

-- 有人掉线的通知
function RegionQuestMgr:HandleQuitPassiveResponse(data)
    if BattleViewMgr then
        -- 如果一方进入战斗已经在加载了，但是另一方掉线了
        cs_coroutine.start(function()
            if BattleViewMgr.battleState < Constants.BattleState.WaitingForStart then
                cs_coroutine.yield_return()
            end
            if BattleViewMgr.battleState == Constants.BattleState.WaitingForStart then
                BattleViewMgr.netMgr:QuitBattle(BattleViewMgr.netMgr.QuitType.OtherDisconnect)
            end
        end)
    end
end

--开始战斗结果
function RegionQuestMgr:HandleStartBattleResponse(data)
    if isNull(self)
    or isNull(self._houseData)
    or self._houseState == HouseState.Destroy then
        -- 防止出现玩家已经退出了房间，但是因为网络问题没有通知到服务器，导致在房间外收到开始战斗的结果
        return
    end
    if BattleViewMgr then return end    -- 如果进入战斗了，就不再响应房间的消息了
    -- 歼灭战的服务器消息异常判断
    if checkNumber(data.result) ~= 0 then
        local msg = AnnihilationUtils.GetServerErrorMgr(checkNumber(data.result))
        GameUtils.Toast(msg)
        if checkNumber(data.result) == 201 then
            local activityPrefabId = self._houseData.activityPrefabId
            local comp = AnnihilationUtils.GetComponent(activityPrefabId)
            comp:BuyHP()
        end
        return
    end

    if isNotNull(self._roleParGo) then
        for i = 1, self:GetMaxTeamAllNum() do 
            local go = self._roleParGo.transform:Find("effect"..i)
            CfUtils.SetActive(go, false)
        end
    end

    self:PushCurModelGo()
    self:ClearModelBuffer()
    GameObject.Destroy(self._bossSceneGo)
    self._bossSceneGo = nil
    cs_coroutine.start(self.Clear, self)

    -- 进入战斗
    if checkInt(data.result) == 0 then
        local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIActionTeamDestoryDialog)
        if dialog then
            dialog.Env:SetStateEnterBattle(true)    -- 通知组队房间界面，关闭的时候不要发送退出房间消息，也不要显示主界面
        end
        -- 如果是断线重连
        if data.isReconnectOutside then
            cs_coroutine.start(function()
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
            end)
        end

        local activityPrefabId = self._houseData.activityPrefabId
        local comp = AnnihilationUtils.GetComponent(activityPrefabId)
        local homeUITypeId = comp:GetHomeUITypeId()
        CfUtils.DialogRecordRemoveTo(homeUITypeId)
    
        data.pvpMode = Constants.PVPMode.Annihilation
        local fightPreWarMgr = FightPreWarMgr:GetInstance()
        fightPreWarMgr:InitPPVEParams(data)
        BattleViewMgr.useVoiceRoom = self.useVoiceRoom
        GameUtils.OpenLoadingPanel(UIArgs(Constants.UITypeIds.BattleScene, {}), nil, Constants.LoadingType.Battle)
    end
end

