function RegionQuestMgr:SetRecruitState(state)
    self._recruitState = state
    Events.Broadcast(Constants.EventNames.RegionRecruitResult, state)

    -- 招募计时
    if state == 1 then
        self:StartRecruitTime()
    else
        self:CloseRecruitTime()
    end
end

--- 开始招募计时
function RegionQuestMgr:StartRecruitTime()
    if isNotNull(self.co_recruitTime) then
        return
    end
    -- 开始计时
    self.recruitTime = 0
    self.co_recruitTime = cs_coroutine.start(function()
        while true do
            self.recruitTime = self.recruitTime + 1
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
        end
        self.co_recruitTime = nil
    end)
end

--- 关闭招募计时
function RegionQuestMgr:CloseRecruitTime()
    self.recruitTime = 0
    if isNotNull(self.co_recruitTime) then
        cs_coroutine.stop(self.co_recruitTime)
        self.co_recruitTime = nil
    end
end

