--刷新人物模型
function RegionQuestMgr:RefreshRoleModel()
    if self._roleModelCo ~= nil then
        cs_coroutine.stop(self._roleModelCo)
        self._roleModelCo = nil
    end
    self._roleModelCo = cs_coroutine.start(function()
        self:PushCurModelGo()
        self._curShowModelGo = {}         --当前展示的模型
    
        local count = 0
        local t = self:GetHostTeam()
        for k, v in pairs(t) do
            local data = v.cardInfo
            if data and checkNumber(data.cardSkin) > 0 then     
                count = count + 1
                local go = self:GetModelGo(data.cardSkin)
                if not isNull(go) then
                    table.insert(self._curShowModelGo, {
                        id = data.cardSkin,
                        go = go,
                    })
                    go.transform.position = self:GetRolePos(k, true)
                    
                    go.transform.localRotation = Quaternion.Euler(self._sceneVo.roleDir.x, self._sceneVo.roleDir.y, self._sceneVo.roleDir.z)
                    KTool.SetActive(go, true)
                end
            end
        end

        for i = 1, self:GetOwnTeamNum() do 
            local go = self._roleParGo.transform:Find("effect"..i)
            if not go then
                local loader = self:GetModleLoader("Effect/prefab/fx_role_ready_01.prefab")
                if not isNull(loader) then
                    go = KTool.Instantiate(self._roleParGo, loader.ResultObject, true)
                    if not isNull(go) then
                        go.name = "effect"..i
                    end
                end
            end
            go.transform.position = self:GetRolePos(i, true)

            CfUtils.SetActive(go, i > count)
        end

        count = 3
        local t = self:GetInvitateTeam()
        for k, v in pairs(t) do
            local data = v.cardInfo
            if data and checkNumber(data.cardSkin) > 0 then    
                count = count + 1 
                local go = self:GetModelGo(data.cardSkin)
                if not isNull(go) then
                    table.insert(self._curShowModelGo, {
                        id = data.cardSkin,
                        go = go,
                    })
                    go.transform.position = self:GetRolePos(k, false)
                    
                    go.transform.localRotation = Quaternion.Euler(self._sceneVo.roleDir.x, self._sceneVo.roleDir.y, self._sceneVo.roleDir.z)
                end
            end
        end

        for i = 1 + 3, self:GetOwnTeamNum() + 3 do 
            local go = self._roleParGo.transform:Find("effect"..i)
            if not go then
                local loader = self:GetModleLoader("Effect/prefab/fx_role_ready_01.prefab")
                if not isNull(loader) then
                    go = KTool.Instantiate(self._roleParGo, loader.ResultObject, true)
                    if not isNull(go) then
                        go.name = "effect"..i
                    end
                end
            end
            go.transform.position = self:GetRolePos(i - 3, false)

            CfUtils.SetActive(go, i > count)
        end

        self:ClearModelBuffer()
    end)
end

function RegionQuestMgr:ClearModelBuffer()
    if isNull(self._modelBuffer) then
        return
    end

    for k, v in pairs(self._modelBuffer) do
        local t = checkTable(v)
        for _, go in pairs(t) do
            if not isNull(go) then
                GameObject.Destroy(go)
            end
        end
    end
    self._modelBuffer = {}
end

--清除当前的
function RegionQuestMgr:PushCurModelGo()
    if not self._curShowModelGo then
        return
    end
    if isNull(self._modelBuffer) then
        self._modelBuffer = {}
    end

    print(table.dump(self._curShowModelGo))

    for k, v in pairs(self._curShowModelGo) do
        local t = self._modelBuffer[checkString(v.id)]
        if t then
            table.insert(self._modelBuffer[checkString(v.id)], v.go)
        else
            self._modelBuffer[checkString(v.id)] = {}
            table.insert(self._modelBuffer[checkString(v.id)], v.go)
        end
    end
end

function RegionQuestMgr:GetModelGo(skinId)
    if isNull(self._modelBuffer) then
        self._modelBuffer = {}
    end
    local skinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", skinId)
    local modelId = checkString(skinVo.mode)

    --创建
    if isNull(self._modelBuffer[checkString(skinId)]) then
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting274, "ModelVo", modelId)
        if not vo then
            return nil
        end

        local path = "Arts/Prefab/"..vo.modelRes..".prefab"
        local loader = self:GetModleLoader(path, nil, true)
        if not isNull(loader) then
            local go = KTool.Instantiate(self._roleParGo, loader.ResultObject, true)
            if not isNull(go) then
                go.name = checkString(skinId)
            end
            return go
        end
    end
    local t = self._modelBuffer[checkString(skinId)]
    local go = t[#t]
    table.remove(t, #t)
    if #t == 0 then
        self._modelBuffer[checkString(skinId)] = nil
    end
    return go
end

function RegionQuestMgr:GetModleLoader(path)
    if isNull(self._roleLoaders) then
        return nil
    end
    path = checkString(path)
    --创建
    if isNull(self._roleLoaders[path]) then
        local roleLoader = ResourceModule.LoadBundleAsync(path, nil, true)
        while not roleLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if roleLoader.IsSuccess then
            self:PushRoleLoader(roleLoader, path) 
        else
            roleLoader:Release()
            return nil
        end
        return roleLoader
    end
    return self._roleLoaders[path]
end

function RegionQuestMgr:PushRoleLoader(loader, path)
    if not self._roleLoaders then
        self._roleLoaders = {}
    end
    if not isNull(self._roleLoaders[checkString(path)]) then
        printError("角色loader pool有泄露")
    end
    self._roleLoaders[checkString(path)] = loader
end


