--自己的编队
function RegionQuestMgr:GetOwnTeam(isTeamShow)
    local t = {}
    if not isNull(self._ownInfo.mainTeamSet) and not isNull(self._ownInfo.mainTeamSet.cardsInfo) then
        for k, v in pairs(self._ownInfo.mainTeamSet.cardsInfo) do
            if v.cardInfo then
                v.cardId = v.cardInfo.cardId
            end
            table.insert(t, v)  
        end
    end

    if table.count(t) < self:GetOwnTeamNum() then
        for i = table.count(t) + 1, self:GetOwnTeamNum() do
            local dojo = CfUtils.GetTeamMemberDojo()
            table.insert(t, dojo)
        end
    end
    if isTeamShow then
        table.insert(t, {})
    end
    return t
end

--别人的编队
function RegionQuestMgr:GetOtherTeam(isTeamShow)
    local t = {}
    if not isNull(self._otherInfo.mainTeamSet) and not isNull(self._otherInfo.mainTeamSet.cardsInfo) then
        for k, v in pairs(self._otherInfo.mainTeamSet.cardsInfo) do
            if v.cardInfo then
                v.cardId = v.cardInfo.cardId
                v.type = Constants.TeamMemberType.HelperCard
            end
            table.insert(t, v)  
        end
    end

    if table.count(t) < self:GetOwnTeamNum() then
        for i = table.count(t) + 1, self:GetOwnTeamNum() do
            local dojo = CfUtils.GetTeamMemberDojo()
            table.insert(t, dojo)
        end
    end
    if isTeamShow then
        table.insert(t, {})
    end

    return t
end

