-- 一级地图
---@return UnityEngine.GameObject
function RegionQuestMgr:GetPrimaryMapGo(mapName)
    if isNull(self._primaryMapGo) then
        local dynamicNodeGo = GameObject.Find("DynamicNode")
        if isNull(dynamicNodeGo) then
            dynamicNodeGo = GameObject("DynamicNode")
        end

        local prefabName   = mapName == nil and 'AreaMap_01' or mapName
        local prefabPath   = string.fmt('Arts/Prefab/MainQuestMap/Prefab/%1.prefab', prefabName)
        local prefabLoader = ResourceModule.LoadBundleAsync(prefabPath, nil, true)
        while not prefabLoader.IsCompleted do
            coroutine.yield(Yielders.EndOfFrame)
        end
        if prefabLoader.IsSuccess then
            local go = prefabLoader:Instantiate(dynamicNodeGo.transform, false)
            go.name  = prefabName
            self._primaryMapGo = go
        end
        prefabLoader:Release()
    end
    return self._primaryMapGo
