--获取人物的位置
function RegionQuestMgr:GetRolePos(ind, isOwn)
    local activityPrefabId = self._houseData.activityPrefabId
    local bossTypeId = self._houseData.bossTypeId
    local comp = AnnihilationUtils.GetComponent(activityPrefabId)
    local vo = comp:GetTypeVo(bossTypeId)
    if not vo then
        return Vector3(0, 0, 0)
    end

    local t = {}
    if isOwn then
        t = checkTable(CfUtils.Split(vo.teamLocation1, ";"))
    else
        t = checkTable(CfUtils.Split(vo.teamLocation2, ";"))
    end

    local data = t[checkNumber(ind)]
    if not data then
        return Vector3(0, 0, 0)
    end

    local t1 = checkTable(CfUtils.Split(data, ","))
    return Vector3(checkNumber(t1[1]), checkNumber(t1[2]), checkNumber(t1[3]))
end

function RegionQuestMgr:GetEnemyPos(ind)
    local t = self:GetAllTeam()
    local total = 1

    local min = self._enemyPath.MinPos
    local max = self._enemyPath.MaxPos
    local pathLength = self._enemyPath.PathLength

    --然后获得相邻距离,少除一份,两边距离等于只占一半
    local edge = (max - min) / total
    --然后按顺序一个个给值
    local nowValue = min - edge / 2
    for i= 1, total do
        nowValue = nowValue + edge
        local pos = self._enemyPath:EvaluatePosition(nowValue)
        if i == ind then
            return pos
        end
    end

    return Vector3(0, 0, 0)
end

