--加载场景
function RegionQuestMgr:LoadScene(questId)
    ---关一下咖啡厅的虚拟相机
    Events.Broadcast("MaidCoffee_VimCraStageChange",false)
    local time = GameUtils.ShowBlackOverlay(nil, function()
        while not self._isLoadSuccess do
            coroutine.yield(Yielders.EndOfFrame)
        end
    end)
    --等屏幕黑了再开始加载  要不ka
    coroutine.yield(WaitForSeconds(time))
    self:ClearCurMapGo()
    self:ClearPrimaryMapGo()

    --self:InitLoadingUI()
    local sceneName = self._sceneVo.sceneName
    local loader = ResourceModule.LoadBundleAsync("Scenes/".. sceneName ..".unity", nil, true)
    while not loader.IsSuccess do
        cs_coroutine.yield_return()
    end
    if loader.IsError then
        loader:Release(true)
        return
    end
    if not loader.ResultObject then
        loader:Release(true)
        return
    end

    self._sceneLoader = loader
    local operation = SceneManager.LoadSceneAsync(sceneName, SceneManagement.LoadSceneMode.Additive)
    operation.allowSceneActivation = false
    if not operation.isDone then
        while operation.progress < 0.8 do
            coroutine.yield()
            --self:OnLoadingProgress(checkNumber(operation.progress) * 100)
        end
        operation.allowSceneActivation = true

        while not operation.isDone do
            --self:OnLoadingProgress(checkNumber(operation.progress) * 100)
            coroutine.yield()
        end
        operation.allowSceneActivation = true

        while not operation.isDone do
            --self:OnLoadingProgress(checkNumber(operation.progress) * 100)
            coroutine.yield()
        end
    end
    local scene = SceneManagement.SceneManager.GetSceneByName(sceneName)
    self._scene = scene
    self._sceneCam = self:GetSceneCam(scene)
    if not isNull(self._sceneCam) then
        local t = self:GetHouseInfo()
        local activityPrefabId = t.activityPrefabId
        local bossTypeId = t.bossTypeId
        local comp = AnnihilationUtils.GetComponent(activityPrefabId)
        local vo = comp:GetTypeVo(bossTypeId)
        if vo then
            local _t = CfUtils.Split(vo.cameraPosition)
            self._sceneCam.transform.position = Vector3(checkNumber(_t[1]), checkNumber(_t[2]), checkNumber(_t[3]))
            _t = CfUtils.Split(vo.cameraRotation)
            self._sceneCam.transform.localRotation = Quaternion.Euler(checkNumber(_t[1]), checkNumber(_t[2]), checkNumber(_t[3]))
        end

        local urpBase = self._sceneCam:GetComponent(typeof(URPBaseCamera))
        urpBase:CopyCamera() 
    end

    self._roleParGo = GameObject.Find('RootNode')
    if isNull(self._roleParGo) then
        self._roleParGo = GameObject('RootNode')
    end
    CS.UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(self._roleParGo, scene)

    self._allGos = {}
    local t = self._scene:GetRootGameObjects()
    for i, v in array_pairs(t) do
        if not KTool.IsNull(v) then
            table.insert(self._allGos, v)
        end
    end

    --self:OnLoadingProgress(1)
    self._isInitScene = true
    self._isLoadSuccess = true
end

function RegionQuestMgr:GetSceneCam(scene)
    local rootObjects = scene:GetRootGameObjects()
    for i, v in array_pairs(rootObjects) do
        if not KTool.IsNull(v) then
            if v.name == "MainCamera" then
                return v                
            end
        end
    end
    return nil
end

function RegionQuestMgr:InitLoadingUI()
    if not self._loadingUI then
        local go = GameObject.Find("LoadingPanel")
        if isNull(go) then
            GameUtils.OpenLoadingPanel()
            go = GameObject.Find("LoadingPanel")
        end
        self._loadingUI = CfUtils.GetLuaScr(go, "Game.Behaviours.UILoadingPanel")
    end
end

function RegionQuestMgr:OnLoadingProgress(num)
    self._loadingUI:Progress(num)
    if num == 1 then
        self._loadingUI:Close()
    end
end

function RegionQuestMgr:ClearPrimaryMapGo()
    if not isNull(self._primaryMapGo) then
        GameObject.Destroy(self._primaryMapGo)
    end
    self._primaryMapGo = nil
end

--一级大地图的动画
function RegionQuestMgr:PlayRegionMapAnimation(id)
    local mapGo = self:GetCurMapGo(id)
    local camGo = mapGo.transform:Find("AreaMap_01_01_Camera")
    CfUtils.SetActive(camGo, false)

    mapGo = self:GetPrimaryMapGo(id)
    CfUtils.PlayAnimation(mapGo.transform:Find("AreaMap_01_plane"), "AreaMap_01_plane_Out_0"..id)
end

---PlayPrimaryMapCrossFadeToSecond
---@param id integer @ second map id
---@param cb fun():void
function RegionQuestMgr:PlayPrimaryMapCrossFadeToSecond(id, cb)
    CfUtils.StartCoroutineWithBlocker(function()
        local secondMap = RegionQuestMgr:GetInstance():GetCurMapGo(id)
        local primaryMap = RegionQuestMgr:GetInstance():GetPrimaryMapGo()
        --primaryMap.transform:SetZ(0)
        local planGo = secondMap.transform:Find("AreaMap_01_0" .. id .. "_plane")
        local parGo = secondMap.transform:Find("ParticleSystem")
        if not isNull(parGo) then
            CfUtils.SetActive(parGo, false)
        end
        CfUtils.SetActive(planGo, false)
        local allPoints = ActionUtils.GetAllRegionSecondMapPointId(id)
        for _, v in pairs(allPoints) do
            ---@type RegionSecondaryMapVo
            local data = ActionUtils.GetRegionSecondaryMapVo(v)
            local isUnlock = ActionUtils.IsUnlockRegionalSecondPoint(data.id)
            local greyGo = planGo.transform:Find("GreyGroup/AreaMap_grey_" .. data.id)
            local effectGo = planGo.transform:Find("EffectGroup/Effect_" .. data.id)
            CfUtils.SetActive(greyGo, not isUnlock)
            CfUtils.SetActive(effectGo, isUnlock)
        end
        RegionQuestMgr:GetInstance():PlayRegionMapAnimation(id)
        CfUtils.SetActive(planGo, true)
        CfUtils.PlayAnimation(planGo, "AreaMap_01_0" .. id .. "_plane_Entry")
        coroutine.yield(CoYield(0.2))
        --CfUtils.SetActive(primaryMap, false)
        if cb then
            cb()
        end
    end)
end

function RegionQuestMgr:PlaySecondMapAnimation(id)
    local vo = ActionUtils.GetRegionSecondaryMapVo(id)
    local mapGo = self:GetCurMapGo(vo.regionBelong)
    local mapCam = mapGo.transform:Find("AreaMap_01_01_Camera").gameObject:GetComponent(typeof(Camera))

    local fPos = mapCam.transform.position
    local targetGo = mapGo.transform:Find("CameraEndPos_"..id)
    local tPos = Vector3(0, 0, 0)
    if targetGo then
        tPos = targetGo.transform.position
    end

    self:SetLastCamPos(fPos, id)

    local urpBase = mapCam:GetComponent(typeof(URPBaseCamera))
    CfUtils.DoTween(0.75, function(updateValue)
        mapCam.transform.position = CS.UnityEngine.Vector3.Lerp(fPos, tPos, updateValue)
        urpBase:CopyCamera() 
    end, function()
    end)
end

function RegionQuestMgr:ClearCurMapGo()
    if not isNull(self._bossGo) then
        GameObject.Destroy(self._bossGo)
    end
    if not isNull(self._curMapGo) then
        GameObject.Destroy(self._curMapGo)
    end
    if not isNull(self._mapLoader) then
        self._mapLoader:Release()
    end
    
    self._bossGo = nil
    self._curMapGo = nil
    self._mapLoader = nil
    self._curMapId = 0
end

function RegionQuestMgr:SpecialJump(targetPointId)
    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self._co = cs_coroutine.start(function()
        local isSuc = false
        local time = GameUtils.ShowBlackOverlay(nil, function()
            while not isSuc do
                coroutine.yield(Yielders.EndOfFrame)
            end
        end)
        --等屏幕黑了再开始加载  要不ka
        coroutine.yield(WaitForSeconds(time))
        coroutine.yield(UIModule.BackDialog())

        local vo = ActionUtils.GetRegionSecondaryMapVo(targetPointId)
        KCookie.Set("UIActionSecondMapDialogtargetPointId", targetPointId)
        coroutine.yield(UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionSecondMapDialog, parameters = {id = vo.regionBelong}}, {
            {id = Constants.UITypeIds.UIActionPrimaryMapDialog }
        }))
        
        isSuc = true
    end)
end

function RegionQuestMgr:SetSceneActive(isTrue)
    if isNull(self._allGos) then
        return
    end
    if isNull(self._scene) then
        return
    end
    SceneManager.SetActiveScene(self._scene)

    for k, v in pairs(self._allGos) do
        if not isNull(v) then
            CfUtils.SetActive(v, isTrue)
        end
    end
end

