function RegionQuestMgr:Clear()
    if self._roleModelCo ~= nil then
        cs_coroutine.stop(self._roleModelCo)
        self._roleModelCo = nil
    end
    
    if self._co ~= nil then
        cs_coroutine.stop(self._co)
        self._co = nil
    end

    -- 移除事件
    -- Events.RemoveListener(Constants.EventNames.GAME_TCP_DISCONNECT, self.eventOnTcpDisconnect)
    Events.RemoveListener(Constants.EventNames.GAME_TCP_CONNECT, self.eventOnTcpConnect)
    Events.RemoveListener(Constants.EventNames.TeamRoomReconnectResponse, self.eventOnTeamRoomReconnect)
    Events.RemoveListener(Constants.EventNames.ExecuteBackHome, self.eventOnBackToHome)

    KCookie.RemoveAllListener(Constants.UICacheDataKeys.OVERSEA_ANNIHILATION_KEY)
    self:CloseRecruitTime()
    self:ClearCurMapGo()

    if not isNull(self._sceneVo) then 
        local sceneName = self._sceneVo.sceneName
        cs_coroutine.yield_return(CS.UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(sceneName))
        if self._sceneLoader then
            self._sceneLoader:Release(true)
            self._sceneLoader = nil
        end
    end

    self:__delete()
    self.Destroy(self)   --这个好像没用
end

--- 歼灭战组队房间，监听home键，清理组队房间
function RegionQuestMgr:OnBackToHome()
    if GameUtils.IsInAnnihilation() then
        cs_coroutine.start(function()
            CoYield(self:Clear())
            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)
        end)
    end
end

--- 主TCP发送组队房间重连
function RegionQuestMgr:OnTcpConnect()
    -- 发送房间的重连消息
    AppService:GetInstance():SendTcpData(Constants.Packets.TeamRoomReconnectRequest, {roomId = self._houseData.roomId, activityUuid = self._houseData.activityUuid})
end

--- 组队房间重连回执
---@param data any
function RegionQuestMgr:OnTeamRoomReconnect(data)
    UIRaycastBlocker:RemoveAll()    -- 重连以后清除阻塞层
    local result = checkNumber(data.result)
    if result ~= 0 then
        if result == 1 then
            self._kickOutState = 2
        elseif result == 2 then
            self._kickOutState = 1
        elseif result == 3 then
            self._kickOutState = 1
        else
            self._kickOutState = 1
            GameUtils.Toast(localize("重连时房间状态异常 _num_", {_num_ = result}))
        end
        Events.Broadcast(Constants.EventNames.RegionTeamQuite)
        return
    end
    local response = data.data
    self:SyncRoom(response)
    self:RefreshRoleModel()
    Events.Broadcast(Constants.EventNames.TeamRoomReconnectRefreshDisplay)
end

--- 同步房间数据
---@param data any
function RegionQuestMgr:SyncRoom(data)
    local readyPlayerIds = checkTable(data.readyPlayerIds)
    for i, v in ipairs(readyPlayerIds) do
        readyPlayerIds[i] = checkNumber(v)
    end
    local mainPlayerInfo = checkTable(data.mainPlayerInfo)  -- 房主
    local subPlayerInfo = checkTable(data.subPlayerInfo)    -- 房客
    local mainTeamSet = checkString(data.mainTeamSet)
    local subTeamSet = checkString(data.subTeamSet)
    local status = checkNumber(data.status)
    local isRobot = checkNumber(data.isRobot)   -- 房客是否是机器人 0真人 1机器人

    local houseOwnerInfo = self._isHouseOwn and self._ownInfo or self._otherInfo
    local houseOtherInfo = self._isHouseOwn and self._otherInfo or self._ownInfo

    houseOwnerInfo.playerInfo = mainPlayerInfo
    houseOtherInfo.playerInfo = subPlayerInfo

    local t = checkTable(table.deserialize(mainTeamSet))
    if t[1] then
        houseOwnerInfo.mainTeamSet = t[1]
    end
    t = checkTable(table.deserialize(subTeamSet))
    if t[1] then
        houseOtherInfo.mainTeamSet = t[1]
    end

    local ownerPlayerId = checkNumber(houseOwnerInfo.playerInfo.playerId)
    houseOwnerInfo.readyState = table.isContain(readyPlayerIds, ownerPlayerId) and 1 or 0
    local otherPlayerId = checkNumber(houseOtherInfo.playerInfo.playerId)
    houseOtherInfo.readyState = table.isContain(readyPlayerIds, otherPlayerId) and 1 or 0

    houseOtherInfo.isRobot = isRobot
    
    self._houseState = table.count(subPlayerInfo) > 0 and HouseState.InviteSuc or HouseState.None
    if houseOtherInfo.readyState == 1 then
        self._houseState = HouseState.ReadySuc
    end

    self._recruitState = 0  -- 掉线时服务器会自动关闭招募
end

return RegionQuestMgr
